export type Tone = "live" | "warn" | "danger" | "outline";

/**
 * The tone each state word is drawn in. States that are not listed are drawn as
 * outline. Add the app's own states here, so that every badge and dot agrees.
 */
const TONES: Record<string, Tone> = {
  running: "live",
  online: "live",
  active: "live",
  healthy: "live",
  starting: "warn",
  stopping: "warn",
  pending: "warn",
  connecting: "warn",
  reconnecting: "warn",
  degraded: "warn",
  failed: "danger",
  error: "danger",
  offline: "danger",
  stopped: "outline",
  idle: "outline",
  disabled: "outline",
};

/** States whose word on screen is not the state name itself. */
const LABELS: Record<string, string> = {};

export function statusTone(state: string): Tone {
  return TONES[state.toLowerCase()] ?? "outline";
}

export function statusLabel(state: string): string {
  const key = state.toLowerCase();
  return LABELS[key] ?? key.charAt(0).toUpperCase() + key.slice(1);
}

import { expect, it } from "vitest";
import { statusLabel, statusTone } from "./status-text";

it("gives every state a tone, and an unknown state the outline one", () => {
  expect(statusTone("running")).toBe("live");
  expect(statusTone("degraded")).toBe("warn");
  expect(statusTone("failed")).toBe("danger");
  expect(statusTone("stopped")).toBe("outline");
  expect(statusTone("something-new")).toBe("outline");
});

it("matches a state whatever its case", () => {
  expect(statusTone("RUNNING")).toBe("live");
  expect(statusLabel("FAILED")).toBe("Failed");
});

it("shows an unlisted state under its own name, capitalised", () => {
  expect(statusLabel("running")).toBe("Running");
  expect(statusLabel("warming-up")).toBe("Warming-up");
});

import { Badge } from "@/ui/primitives/badge";
import { statusLabel, statusTone } from "@/ui/status-text";
import { cn } from "@/ui/utils";

export function StatusDot({ state, className }: { state: string; className?: string }) {
  const tone = statusTone(state);
  return (
    <span
      aria-hidden
      className={cn(
        "inline-block size-1.5 shrink-0 rounded-full",
        tone === "live" && "bg-online",
        tone === "warn" && "bg-degraded",
        tone === "danger" && "bg-danger status-pulse",
        tone === "outline" && "bg-offline",
        className,
      )}
    />
  );
}

/** Status is always text plus colour: the dot is decoration and the word is the name. */
export function StatusBadge({ state }: { state: string }) {
  return (
    <Badge variant={statusTone(state)} className="gap-1.5 whitespace-nowrap">
      <StatusDot state={state} />
      {statusLabel(state)}
    </Badge>
  );
}
